// === Merge safety checks ===
// Mode: "Run Once for All Items".
// Input = the loser ticket's comments (from "Zendesk: Get loser comments").
//
// Re-verifies everything live before writing. Safe to call twice for the same
// pair - the second call will find the loser closed and skip.

const ACTIVE = new Set(['new', 'open', 'pending', 'hold']);

const cfg = $('Get Project Config').first().json;
const input = $('Restore trigger data').first().json;

const keeperId = Number(input.keeper_ticket_id);
const loserId = Number(input.loser_ticket_id);
const automationAgentId = Number(cfg.automation_agent_id || 0);

const tickets = $('Zendesk: Get both tickets').first().json.tickets || [];
const keeper = tickets.find(t => Number(t.id) === keeperId) || null;
const loser = tickets.find(t => Number(t.id) === loserId) || null;

const comments = $input.first().json.comments || [];

const reasons = [];

if (!keeperId || !loserId) reasons.push('missing_ticket_id');
if (keeperId === loserId) reasons.push('same_ticket');
if (!keeper) reasons.push('keeper_not_found');
if (!loser) reasons.push('loser_not_found');

if (keeper && !ACTIVE.has(String(keeper.status).toLowerCase())) reasons.push('keeper_no_longer_active');
if (loser && !ACTIVE.has(String(loser.status).toLowerCase())) reasons.push('loser_no_longer_active');

if (keeper && loser && Number(keeper.requester_id) !== Number(loser.requester_id)) reasons.push('different_requester');

if (loser && loser.assignee_id) reasons.push('loser_has_assignee');
if (loser) {
  const touchedByAgent = comments.some(c => {
    const author = Number(c.author_id);
    return author !== Number(loser.requester_id) && author !== automationAgentId;
  });
  if (touchedByAgent) reasons.push('loser_touched_by_agent');
}

const safe = reasons.length === 0;

let mergeBody = null;
if (safe) {
  const subject = String(loser.subject == null ? '' : loser.subject).trim();
  const description = String(loser.description == null ? '' : loser.description).trim();

  mergeBody = {
    ids: [loserId],
    target_comment: 'Duplicate ticket #' + loserId + ' from the same requester was merged into this ticket automatically and closed.\n\nSubject: ' + subject + '\n\nMessage from #' + loserId + ':\n' + description,
    target_comment_is_public: false,
    source_comment: 'This ticket was merged into #' + keeperId + ' automatically, because the requester already had an active ticket.',
    source_comment_is_public: false
  };
}

// Set the Duplicate contact category AND the Language field on the loser BEFORE
// merging. Merge closes the loser and a closed ticket cannot be updated, so this
// is the only chance. Language is included because most brands mark it required
// and Zendesk rejects the transition without it:
//   422 RecordInvalid - "Language: is required when solving a ticket"
// Each field is only sent when both its id and its per-brand value are set.
const preMergeFields = [];

const catFieldId = Number(cfg.ticket_custom_field_category);
const dupValue = cfg.category_value_duplicate_contact;
if (Number.isFinite(catFieldId) && catFieldId > 0
    && dupValue !== null && dupValue !== undefined && String(dupValue).trim() !== '') {
  preMergeFields.push({ id: catFieldId, value: String(dupValue) });
}

const langFieldId = Number(cfg.ticket_field_language_id);
const langValue = cfg.language_value_english;
if (Number.isFinite(langFieldId) && langFieldId > 0
    && langValue !== null && langValue !== undefined && String(langValue).trim() !== '') {
  preMergeFields.push({ id: langFieldId, value: String(langValue) });
}

let duplicateLabelBody = null;
if (safe && preMergeFields.length > 0) {
  duplicateLabelBody = { ticket: { custom_fields: preMergeFields } };
}

return [{
  json: {
    safe,
    skip_reasons: reasons,
    keeper_ticket_id: keeperId,
    loser_ticket_id: loserId,
    keeper_status: keeper ? keeper.status : null,
    loser_status: loser ? loser.status : null,
    merge_body: mergeBody,
    duplicate_label_body: duplicateLabelBody,
    pre_merge_fields_applied: preMergeFields.length
  }
}];

